<script lang="ts">
 import {Play,Pause,SkipBack,SkipForward,Gauge,Volume2,VolumeX,Orbit} from 'lucide-svelte';
 import {simulationState,status,save} from '../lib/store';
 import {missionById,chapterFraction,missionDuration,seekMission,stopMission,type MissionState} from '../lib/mission';
 import {missionReady} from '../lib/mission-ui';
 const mission=$derived($simulationState.mission!);
 const doc=$derived(missionById.get(mission.id)!);
 const chapter=$derived(doc.chapters[mission.chapter]);
 const hasAudio=$derived(chapter.media?.some(cue=>cue.kind==='audio')??false);
 const complete=$derived(mission.chapter===doc.chapters.length-1&&mission.elapsed>=chapter.duration);
 const presentation=$derived(doc.chapters.slice(0,mission.chapter).reduce((s,c)=>s+c.duration,0)+mission.elapsed);
 const clock=(s:number)=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
 function patch(change:Partial<MissionState>){simulationState.update(s=>({...s,mission:{...s.mission!,...change}}));}
 function jump(index:number){simulationState.update(s=>({...s,mission:seekMission(s.mission!,index)}));}
 function toggle(){if(complete)simulationState.update(s=>({...s,mission:{...seekMission(s.mission!,0),playing:true}}));else patch({playing:!mission.playing});}
 function stop(){simulationState.update(stopMission);save();status.set('Mission stopped · previous workspace restored · paused');}
</script>
<footer class="mission-timeline" aria-label="Mission playback controls">
 <div class="mission-controls"><div class="mission-title"><span class="eyebrow">APOLLO 11 · GUIDED MISSION</span><strong>{complete?'Mission complete':chapter.title}</strong></div><div class="mission-buttons"><button aria-label="Previous mission chapter" disabled={mission.chapter===0} onclick={()=>jump(mission.chapter-1)}><SkipBack size={18}/></button><button class="mission-play" aria-label={mission.playing?'Pause mission':complete?'Replay mission':'Play mission'} disabled={!$missionReady} onclick={toggle}>{#if mission.playing}<Pause size={19}/>{:else}<Play size={19}/>{/if}</button><button aria-label="Next mission chapter" disabled={mission.chapter===doc.chapters.length-1} onclick={()=>jump(mission.chapter+1)}><SkipForward size={18}/></button><select aria-label="Mission presentation speed" value={mission.rate} onchange={e=>patch({rate:+e.currentTarget.value})}><option value={0.5}>0.5x</option><option value={1}>1x</option><option value={2}>2x</option></select><button aria-label={mission.dashboardVisible===false?'Show flight dashboard':'Hide flight dashboard'} title="dashboard on/off" onclick={()=>patch({dashboardVisible:mission.dashboardVisible===false})}><Gauge size={16}/></button><button aria-label="show/hide trajectories" title="show/hide trajectories" aria-pressed={mission.trajectoriesVisible!==false} onclick={()=>patch({trajectoriesVisible:mission.trajectoriesVisible===false})}><Orbit size={17}/></button><div class="audio-controls" title={hasAudio?'Mission audio':'No audio in this chapter'}><button class="audio-toggle" aria-label={hasAudio?(mission.audioEnabled?'Mute mission audio':'Unmute mission audio'):'No audio in this chapter'} title={hasAudio?(mission.audioEnabled?'Mute audio':'Unmute audio'):'No audio in this chapter'} aria-pressed={hasAudio&&(mission.audioEnabled??false)} disabled={!hasAudio} onclick={()=>patch({audioEnabled:!mission.audioEnabled})}>{#if hasAudio&&mission.audioEnabled&&(mission.audioVolume??.7)>0}<Volume2 size={18}/>{:else}<VolumeX size={18}/>{/if}</button><input class="audio-volume" aria-label="Mission recording volume" title={hasAudio?'Volume':'No audio in this chapter'} disabled={!hasAudio} type="range" min="0" max="1" step="0.05" value={mission.audioVolume??.7} oninput={e=>patch({audioVolume:+e.currentTarget.value})}/></div><button class="stop-mission" onclick={stop}>Exit</button></div><span class="duration">{clock(presentation)} / {clock(missionDuration(doc))}</span></div>
 <progress aria-label="Current mission chapter progress" max="1" value={chapterFraction(mission)}></progress>
 <div class="mission-help"><span>{mission.playing?'Playing':complete?'Finished':'Paused · inspect from any angle'} · Chapter {mission.chapter+1} of {doc.chapters.length}</span><span>Mission clock active · normal time scrubbing is disabled</span></div>
</footer>
<style>
 .mission-timeline{flex-shrink:0;padding:17px 28px 14px;background:#0b131e;border-top:1px solid #dfbd8933}.mission-controls{display:flex;align-items:center;justify-content:space-between;gap:20px}.mission-title{display:flex;flex-direction:column;gap:7px;min-width:170px}.mission-title strong{font-weight:500;color:#e7d1b1;font-size:14px}.mission-buttons{display:flex;gap:8px;align-items:center}.audio-controls{display:flex;align-items:center;gap:6px}.audio-toggle{padding:7px}.audio-volume{width:65px;accent-color:#dfbd89}.audio-toggle:disabled,.audio-volume:disabled{opacity:.3;cursor:default;filter:grayscale(1)}.mission-buttons select{min-width:55px}.mission-play{border-radius:50%;background:#dfbd89;color:#111b27;width:38px;height:38px}.mission-play:hover{color:#111b27;background:#f1d7af}.stop-mission{border-color:#c0a27c55;color:#edcfaa;margin-left:10px}.duration{font-size:11px;color:#9daab9;font-variant-numeric:tabular-nums}.mission-help{display:flex;justify-content:space-between;color:#8190a3;font-size:10px;margin-top:6px}progress{display:block;width:100%;height:4px;margin-top:17px;accent-color:#dfbd89;border:0}progress::-webkit-progress-bar{background:#263241;border-radius:4px}progress::-webkit-progress-value{background:#dfbd89;border-radius:4px}@media(max-width:800px){.mission-timeline{padding:12px}.mission-controls{gap:8px}.mission-title{min-width:0}.mission-title strong{font-size:11px}.duration,.mission-help span:last-child{display:none}.mission-buttons{gap:2px}.mission-buttons select{font-size:10px;width:58px}.stop-mission{margin-left:3px;font-size:11px}.mission-title .eyebrow{font-size:8px}}
</style>
